import test from"node:test";import assert from"node:assert/strict";
import{decideOrchestration,nextCircuitState,classifyBackpressure,sloBurnRate,validateEvent,validateStageRun}from"../dist/index.js";
const event={event_id:"e",event_type:"MATCH.NORMALIZED",schema_version:"0.1",occurred_at:"2026-08-21T12:00:00Z",observed_at:"2026-08-21T11:59:59Z",producer:"normalizer",stage:"NORMALIZATION",correlation_id:"c",causation_id:null,idempotency_key:"k",entity_type:"MATCH",entity_id:"m",payload:{x:1},lineage_refs:["raw1"],attempt:0,status:"SUCCEEDED"};
test("event valid",()=>assert.deepEqual(validateEvent(event),[]));
test("missing dependency waits",()=>assert.equal(decideOrchestration(event,"MODEL",new Set(["DATA_CONTRACT"]),[],null,"2026-08-21T12:00:00Z").action,"WAIT"));
test("idempotent success skips duplicate",()=>{const run={stage_run_id:"r",event_id:"e",stage:"FEATURE_ENGINE",started_at:"2026-08-21T12:00:00Z",completed_at:"2026-08-21T12:00:01Z",status:"SUCCEEDED",attempt:1,input_hash:"fnv1a32:dummy",output_hash:"o",error_code:null,error_message:null,worker_id:"w",immutable:true};const d=decideOrchestration(event,"FEATURE_ENGINE",new Set(["DATA_CONTRACT"]),[],null,"2026-08-21T12:00:00Z");assert.equal(d.action,"RUN")});
test("open circuit blocks",()=>{const c={circuit_id:"x",stage:"MODEL",state:"OPEN",failure_rate:.8,consecutive_failures:6,opened_at:"x",last_transition_at:"x"};assert.equal(decideOrchestration(event,"MODEL",new Set(["FEATURE_ENGINE"]),[],c,"2026-08-21T12:00:00Z").action,"BLOCKED_BY_CIRCUIT")});
test("circuit opens after failures",()=>{let c={circuit_id:"x",stage:"MODEL",state:"CLOSED",failure_rate:0,consecutive_failures:0,opened_at:null,last_transition_at:"2026-08-21T00:00:00Z"};for(let i=0;i<5;i++)c=nextCircuitState(c,false,"2026-08-21T12:00:00Z");assert.equal(c.state,"OPEN")});
test("backpressure pauses stale huge queue",()=>assert.equal(classifyBackpressure("q","x",20000,600,10,30).state,"PAUSED"));
test("SLO burn detects budget burn",()=>assert.ok(sloBurnRate({slo_id:"s",name:"x",stage:null,indicator:"success",target:.99,window_minutes:60,burn_rate_alert_threshold:2},90,100)>1));
test("successful stage run requires output hash",()=>{const x=validateStageRun({stage_run_id:"r",event_id:"e",stage:"MODEL",started_at:"2026-08-21T12:00:00Z",completed_at:"2026-08-21T12:00:01Z",status:"SUCCEEDED",attempt:1,input_hash:"i",output_hash:null,error_code:null,error_message:null,worker_id:"w",immutable:true});assert.equal(x.some(i=>i.code==="MISSING_OUTPUT_HASH"),true)});
